-- GYM PAGLU: Idempotent Master Exercise Catalog Schema Upgrade & Full Seed (348 canonical exercises across 15 categories)
-- Run this in Supabase SQL Editor to upgrade existing tables and populate the full exercise library.

alter table public.exercises
  add column if not exists categories text[] not null default '{}',
  add column if not exists primary_muscle text not null default '',
  add column if not exists secondary_muscles text[] not null default '{}',
  add column if not exists exercise_type text not null default 'Compound',
  add column if not exists difficulty text not null default 'Intermediate',
  add column if not exists target_muscle text not null default '',
  add column if not exists aliases text[] not null default '{}',
  add column if not exists common_mistakes text not null default '',
  add column if not exists media_url text;

create index if not exists idx_exercises_category on public.exercises(category);
create index if not exists idx_exercises_equipment on public.exercises(equipment);
create index if not exists idx_exercises_name_lower on public.exercises(lower(name));

do $$
declare
  c record;
begin
  for c in
    select conname
    from pg_constraint
    where conrelid = 'public.exercises'::regclass
      and contype = 'c'
      and (pg_get_constraintdef(oid) ilike '%category%' or pg_get_constraintdef(oid) ilike '%exercise_type%' or pg_get_constraintdef(oid) ilike '%difficulty%')
  loop
    execute format('alter table public.exercises drop constraint %I', c.conname);
  end loop;

  alter table public.exercises
    add constraint exercises_category_check check (category in (
      'Back', 'Biceps', 'Chest', 'Triceps', 'Legs', 'Shoulders', 'Abs',
      'Forearms', 'Traps', 'Neck', 'Cardio', 'Glutes', 'Full Body',
      'Calisthenics', 'Mobility',
      'Quadriceps', 'Hamstrings', 'Calves', 'Abs and Core', 'Full body'
    )),
    add constraint exercises_type_check check (exercise_type in ('Compound', 'Isolation', 'Cardio', 'Mobility')),
    add constraint exercises_difficulty_check check (difficulty in ('Beginner', 'Intermediate', 'Advanced'));

  for c in
    select conname
    from pg_constraint
    where conrelid = 'public.custom_exercises'::regclass
      and contype = 'c'
      and pg_get_constraintdef(oid) ilike '%category%'
  loop
    execute format('alter table public.custom_exercises drop constraint %I', c.conname);
  end loop;

  alter table public.custom_exercises
    add constraint custom_exercises_category_check check (category in (
      'Back', 'Biceps', 'Chest', 'Triceps', 'Legs', 'Shoulders', 'Abs',
      'Forearms', 'Traps', 'Neck', 'Cardio', 'Glutes', 'Full Body',
      'Calisthenics', 'Mobility',
      'Quadriceps', 'Hamstrings', 'Calves', 'Abs and Core', 'Full body'
    ));
end $$;

grant select on public.exercises to authenticated;
alter table public.exercises enable row level security;
drop policy if exists "Public exercises are readable by authenticated users" on public.exercises;
create policy "Public exercises are readable by authenticated users"
  on public.exercises
  for select
  to authenticated
  using (true);

alter table public.custom_exercises enable row level security;
drop policy if exists "Users manage own custom exercises" on public.custom_exercises;
create policy "Users manage own custom exercises"
  on public.custom_exercises
  for all
  to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

on conflict (name) do update set
  category = excluded.category,
  categories = excluded.categories,
  primary_muscle = excluded.primary_muscle,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  exercise_type = excluded.exercise_type,
  difficulty = excluded.difficulty,
  target_muscle = excluded.target_muscle,
  aliases = excluded.aliases,
  instructions = excluded.instructions,
  common_mistakes = excluded.common_mistakes,
  media_url = excluded.media_url,
  is_compound = excluded.is_compound;
